{
  "paragraphs": [
    {
      "component_id": "concern_001",
      "text": "A wage deduction for a cash shortage is allowed only if (a) the employee is clearly shown to be responsible for the loss, (b) the employee is given a reasonable chance to explain why the deduction should not be made, (c) the deduction is fair, reasonable and does not exceed the actual loss, and (d) the amount taken does not surpass 20 % of the employee’s weekly wages. All these conditions must be met before any deduction can be applied.",
      "evidence": [
        {
          "quote_id": "concern_001.s1.q1"
        },
        {
          "quote_id": "concern_001.s1.q2"
        },
